"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3445],{5371(e){e.exports=JSON.parse('{"title":"React Aria, shadcn registry\uc5d0 \ucc38\uac00\ud558\ub2e4.","date":"2026-01-02","coverUrl":"/kudzu-based-bench/assets/notion/4b91d7024d88db15.png","html":"<h1 data-notion-block-id=\\"2d0e548d-8a8e-800c-8c8b-f7f4303760af\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"2d8e548d-8a8e-807e-827c-d68929968f86\\" id=\\"2d8e548d-8a8e-807e-827c-d68929968f86\\">React Aria, shadcn registry\uc5d0 \ucc38\uac00\ud558\ub2e4.</h2><a href=\\"https://react-aria.adobe.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react-aria.adobe.com/</a><p data-notion-block-id=\\"2d8e548d-8a8e-807a-bd47-f5f58741195d\\">React aria\uac00 \uc0c8\ub85c\uc6b4 docs\ub85c \uc7ac\ud3b8\ud558\uba74\uc11c React spectrum\uc740 marcos\ub97c \ud65c\uc6a9\ud55c version 2\ub97c \ucd9c\uc2dc\ud588\uace0, React aria\ub294 shadcn\uc744 \ud65c\uc6a9\ud55c \ucef4\ud3ec\ub10c\ud2b8 \ucd94\uac00 \ubc29\uc2dd\uc744 \ud65c\uc6a9\ud588\uc2b5\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc18c\uac1c\ud55c <a href=\\"https://ui.shadcn.com/create\\">shadcn create</a>( <a href=\\"https://siosio3103.medium.com/shadcn-2025%EB%85%84-%EB%8C%80%EA%B7%9C%EB%AA%A8-%EC%97%85%EB%8D%B0%EC%9D%B4%ED%8A%B8-%EC%B6%9C%EC%8B%9C-97dd2b193615\\">\ud55c\uad6d\uc5b4 \uc18c\uac1c \ubc88\uc5ed\uae00</a> )\uac19\uc774, React aria\ub610\ud55c \uc790\uc2e0\ub9cc\uc758 \ucef4\ud3ec\ub10c\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub85c \ub9cc\ub4e4 \uc218 \uc788\uac8c \ub3d5\uae30 \ub54c\ubb38\uc5d0(ex. <code>npx shadcn add @react-aria/css-button</code>, <code>npx shadcn add @react-aria/tailwind-button</code>, \ubb3c\ub860 css \ubc29\uc2dd\uc740 shadcn\uc758 \ucca0\ud559\uacfc\ub294 \uc57d\uac04 \uac70\ub9ac\uac00 \uc788\uc2b5\ub2c8\ub2e4) shadcn create\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 Radix UI, Base UI \uae30\ubc18 \ucef4\ud3ec\ub10c\ud2b8 \uc678\uc5d0\ub3c4 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 \uc5ec\ub7ec <a href=\\"https://ui.shadcn.com/docs/directory\\">\ub4f1\ub85d\ub41c \ub77c\uc774\ube0c\ub7ec\ub9ac</a>\uac00 \ub9ce\uc73c\ub2c8 \uc790\uc2e0\uc758 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0 \ub9de\uac8c \uc801\uc6a9\ud574\ubcf4\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2dbe548d-8a8e-80a5-a190-fbab5d56f5f0\\" id=\\"2dbe548d-8a8e-80a5-a190-fbab5d56f5f0\\">RSC\ub294 \uc798 \uad6c\ud604\ud558\uba74 \uc131\ub2a5\uc801\uc73c\ub85c \ucd5c\uace0\ub2e4.</h2><a href=\\"https://calendar.perfplanet.com/2025/intro-to-performance-of-react-server-components/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://calendar.perfplanet.com/2025/intro-to-performance-of-react-server-components/</a><p data-notion-block-id=\\"2d0e548d-8a8e-8064-923f-d997ea1b873f\\">RSC\ub97c \uc774\uc0c1\uc801\uc778 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\uc11c\ub294 CSR, SSR(Client data fetching, Server data fetching)\ubcf4\ub2e4 \uc88b\uc740 \uc131\ub2a5\uc744 \ub0b8\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc5ed\uc2dc, RSC \uad6c\ud604\ubc29\uc2dd\uc774 \ud504\ub808\uc784\uc6cc\ud06c\ub9c8\ub2e4 \ub2e4\ub974\ubbc0\ub85c, \ud2b9\uc815 \ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \uc885\uc18d\ub420 \uc218\ub3c4 \uc788\ub2e4\ub294 \uc810, \uadf8\ub9ac\uace0 \ucd5c\uadfc \uc0ac\ud0dc\ucc98\ub7fc \uc544\uc9c1\uae4c\uc9c0\ub294 \ubd88\uc548\uc815\ud55c \ubaa8\uc2b5\uc744 \ubcf4\uc5ec\uc900\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4. <a href=\\"https://www.epicreact.dev/react-routers-take-on-react-server-components-4bj7q\\">React Router</a>\ub098 <a href=\\"https://tanstack.com/router/v1/docs/framework/react/examples/start-basic-rsc\\">Tanstack start</a>\uc5d0\uc11c\ub3c4 \uad6c\ud604\ud560 \uc218\ub294 \uc788\ub2e4\ub294 \uc810\uc740 \uae0d\uc815\uc801\uc73c\ub85c \uac80\ud1a0\ud574\ubd10\ub3c4 \uc788\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2dbe548d-8a8e-805f-9df2-d0acfcaf44c9\\" id=\\"2dbe548d-8a8e-805f-9df2-d0acfcaf44c9\\">\uc5b4\uca4c\uba74 AI\uac00 \ubc1c\uc804\ud558\uba74\uc11c, \ud504\ub85c\ud1a0\ud0c0\uc785\uc774 \uc0c8\ub85c\uc6b4 PRD\uac00 \ub420 \uc218\ub3c4 \uc788\ub2e4.</h2><a href=\\"https://www.figma.com/blog/prototypes-are-the-new-prds/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.figma.com/blog/prototypes-are-the-new-prds/</a><p data-notion-block-id=\\"2dbe548d-8a8e-80a2-8bf2-e59c6c4dac59\\">\uc5b4\ub5bb\uac8c \ubcf4\uba74 Figma make\ub97c \ud64d\ubcf4\ud558\ub294 \uae00\uc77c \uc218\ub3c4 \uc788\uaca0\uc9c0\ub9cc, \ucd94\ud6c4\uc5d0\ub294 \ucd08\uae30 \uc544\uc774\ub514\uc5b4\uac00 PRD\ub85c \ub9cc\ub4dc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c Figma make\ub098 Stitch\uac19\uc740 AI \uae30\ubc18 \ud504\ub86c\ud3ec\ud2b8\ub85c \ub9cc\ub4dc\ub294 \ub514\uc790\uc778 \ud234\uc774 \uc9c4\uc2e4\uc758 \uc6d0\ucc9c\uc73c\ub85c \ud1b5\ud569\ub420 \uc218\ub3c4 \uc788\uaca0\ub2e4\ub294 \uad00\uc810\uc744 \uc904 \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2dbe548d-8a8e-806d-a00c-f9a216cf91d4\\" id=\\"2dbe548d-8a8e-806d-a00c-f9a216cf91d4\\">\ubc88\ub4e4\ub7ec\ub294, \uc774\uc81c \uc18d\ub3c4\ubcf4\ub2e4 \ub2e4\ub978 \ubd80\ubd84\uc744 \uc2e0\uacbd\uc368\uc57c \ud55c\ub2e4</h2><a href=\\"https://redmonk.com/kholterhoff/2025/12/16/javascript-bundler-grand-prix/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://redmonk.com/kholterhoff/2025/12/16/javascript-bundler-grand-prix/</a><p data-notion-block-id=\\"2dbe548d-8a8e-8089-8575-d7650c11c85d\\">\ubc88\ub4e4\ub7ec\uc758 \uc18d\ub3c4\ub294 Parcel\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \ub2e4\ub978 \uc5b8\uc5b4\ub85c \uc774\ub8e8\uc5b4\uc9c4 ESBuild, Bun, \u2026 \uc5ec\ub7ec\uac00\uc9c0 \uc5c4\uccad\ub098\uac8c \ube60\ub978 \ubc88\ub4e4\ub7ec\ub4e4\uc774 \ub9ce\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc Tree shaking\ubc29\uc2dd(<a href=\\"https://ones-to-watch.ethansup.net/news/post/2a7e548d-8a8e-8035-8091-f96685017e48#2aee548d-8a8e-8043-83ec-fffe6be54735\\">\ubc88\ub4e4\ub7ec\ub9c8\ub2e4 Tree shaking\uc740 \uc5b4\ub5bb\uac8c \ub2e4\ub97c\uae4c</a>)\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \ud1b5\ud569 \ud234\uc744 \uc9c0\uc6d0\ud558\uac70\ub098, \ud2b9\ubcc4\ud55c \uae30\ub2a5\uc744 \uc9c0\uc6d0\ud558\ub294 \ub4f1 \uc5ec\ub7ec\uac00\uc9c0 \ud2b9\uc9d5\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc774\uc81c, \ubc88\ub4e4\ub7ec\uc758 \uc18d\ub3c4\ub294 \ud55c\uacc4\uae4c\uc9c0 \ube68\ub77c\uc84c\uae30\uc5d0, \uc5ec\ub7ec\uac00\uc9c0 \ud2b9\uc9d5\uc774\ub098, \ud639\uc740 \uae00\uc5d0\uc11c \ub098\uc628 \uac83\ucc98\ub7fc, \ube4c\ub4dc \uacb0\uacfc\ubb3c \ud06c\uae30\uac00 \uc5bc\ub9c8\ub098 \ud074\uc9c0(ex. <a href=\\"https://github.com/privatenumber/minification-benchmarks\\">minification benchmark</a>)\uc5d0 \ub300\ud574 \uacbd\uc7c1\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ubbf8\ub798\ub294 \uc544\ubb34\uac83\ub3c4 \ubaa8\ub974\uaca0\uc8e0.</p><h1 data-notion-block-id=\\"2d0e548d-8a8e-800f-a036-f9edd1ac1dde\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"2d0e548d-8a8e-80c2-9a60-cc8dae1a1ba2\\" id=\\"2d0e548d-8a8e-80c2-9a60-cc8dae1a1ba2\\">RSC \ud504\ub85c\ud1a0\ucf5c\uc740 \uc5b4\ub5bb\uac8c \uc774\ub8e8\uc5b4\uc838 \uc788\uc744\uae4c</h2><a href=\\"https://overreacted.io/introducing-rsc-explorer/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://overreacted.io/introducing-rsc-explorer/</a><p data-notion-block-id=\\"2dbe548d-8a8e-80fa-9d52-c9478712b799\\">RSC \ucde8\uc57d\uc810\uc73c\ub85c RSC \ud504\ub85c\ud1a0\ucf5c\uc774 \uc8fc\ubaa9\ubc1b\ub294 \uc9c0\uae08, RSC \ud504\ub85c\ud1a0\ucf5c(React Flight)\uac00 \uc5b4\ub5bb\uac8c \uc774\ub8e8\uc5b4\uc838\uc788\ub294\uc9c0 \ub2e8\uacc4\ubcc4\ub85c \ubcfc \uc218 \uc788\ub294 \uc778\ud130\ub809\ud2f0\ube0c \ub3c4\uad6c\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2dbe548d-8a8e-80c1-bbb7-f742686148bf\\" id=\\"2dbe548d-8a8e-80c1-bbb7-f742686148bf\\">React Compiler\ub294 \uc624\ub958\ub97c \ubcf4\uc5ec\uc8fc\uc9c0 \uc54a\ub294\ub2e4.</h2><a href=\\"https://acusti.ca/blog/2025/12/16/react-compiler-silent-failures-and-how-to-fix-them/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://acusti.ca/blog/2025/12/16/react-compiler-silent-failures-and-how-to-fix-them/</a><p data-notion-block-id=\\"2dbe548d-8a8e-80f3-a6b2-e0339cc335f3\\">\ud68c\uc0ac\uc758 React Compiler \ub3c4\uc785 6\uac1c\uc6d4 \uc774\ud6c4, React Compiler\uac00 UX \uc624\ub958\ub97c \ubc49\uc5c8\uace0, \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. React Compiler\uac00 stable \ubc84\uc804\uc5d0 \uc62c\ub77c\uc654\uc74c\uc5d0\ub3c4 \ucef4\ud30c\uc77c\ub7ec\uac00 \uace0\uc7a5\ub0a0 \uc218\ub3c4 \uc788\ub294 \ud3ec\uc778\ud2b8\uac00 \uc544\uc9c1 \ub0a8\uc544\uc788\ub2e4\ub294 \uac83\uc744 \uba85\uc2ec\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2dbe548d-8a8e-8068-bcb6-c80197dcb7ec\\" id=\\"2dbe548d-8a8e-8068-bcb6-c80197dcb7ec\\">2025\ub144 HTML\uc758 \uc0c1\ud0dc\ub294?</h2><a href=\\"https://2025.stateofhtml.com/ko-KR/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2025.stateofhtml.com/ko-KR/</a><h2 data-notion-block-id=\\"2d0e548d-8a8e-8074-93a7-cb7649a3f1d2\\" id=\\"2d0e548d-8a8e-8074-93a7-cb7649a3f1d2\\">UX\uac00 \ud6a8\uacfc\uc801\uc778\uc9c0 \uce21\uc815\ud558\ub824\uba74</h2><a href=\\"https://www.smashingmagazine.com/2025/12/how-measure-impact-features-tars/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2025/12/how-measure-impact-features-tars/</a><p data-notion-block-id=\\"2d0e548d-8a8e-805c-88d7-e479c68fd1e0\\">UX\uac00 \ud6a8\uacfc\uc801\uc778\uc9c0 \uce21\uc815\ud558\uae30 \uc704\ud574 \uac04\ub2e8\ud55c \uc9c0\ud45c\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2dbe548d-8a8e-8078-a2a4-fb8a2754af3c\\" id=\\"2dbe548d-8a8e-8078-a2a4-fb8a2754af3c\\">TypeScript\uc758 \ubaa8\ub4e0 \uac83, \uac04\ub2e8\ud558\uac8c</h2><a href=\\"https://github.com/gibbok/typescript-book\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/gibbok/typescript-book</a><p data-notion-block-id=\\"2dbe548d-8a8e-801a-b88e-d56ef0f519b2\\">\uac04\ub2e8\ud558\uac8c TypeScript\uc758 \ubaa8\ub4e0 \uac83\uc744 \ud6d1\ub294 \ucc45 \ud615\uc2dd\uc758 \uae43\ud5c8\ube0c \uc800\uc7a5\uc18c\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2dbe548d-8a8e-8060-85ef-ff75b0f53c54\\" id=\\"2dbe548d-8a8e-8060-85ef-ff75b0f53c54\\">React Native \ub514\ubc84\uae45\uc774 \ub354 \uc26c\uc6cc\uc84c\ub2e4.</h2><a href=\\"https://blog.swmansion.com/react-native-debugging-new-performance-panel-in-react-native-0-83-21ca90871f6d\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.swmansion.com/react-native-debugging-new-performance-panel-in-react-native-0-83-21ca90871f6d</a><h1 data-notion-block-id=\\"2d0e548d-8a8e-8031-85c5-ff19e3032edc\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://github.com/mui/base-ui/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/mui/base-ui/</a><p data-notion-block-id=\\"2d5e548d-8a8e-8029-a87e-d4286261fd9f\\">\uc5ec\ub7ec \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9cc\ub4e4\ub358 \ubd84\ub4e4\uc774 \ub9cc\ub4e0 Base UI\uac00 1\ubc84\uc804 \ucd9c\uc2dc\ub97c \ud588\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://storybook.js.org/blog/security-advisory/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://storybook.js.org/blog/security-advisory/</a><p data-notion-block-id=\\"2d1e548d-8a8e-8047-83ee-de793fb5c66d\\">\ub2a6\uc5c8\uc9c0\ub9cc, Storybook\uc774 \ud658\uacbd\ubcc0\uc218\ub97c \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud558\ub294\uc9c0\uc5d0 \ub300\ud55c \ubcf4\uc548 \uc774\uc288\uac00 \uc788\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://nodejs.org/ko/blog/vulnerability/december-2025-security-releases\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejs.org/ko/blog/vulnerability/december-2025-security-releases</a><p data-notion-block-id=\\"2dbe548d-8a8e-8094-b9a1-f67b14cf6a2e\\">\ubbf8\ub9ac, Node.js\uc758 \ubcf4\uc548 \uc774\uc288\uac00 \uc788\uc74c\uc744 \ubcf4\uace0\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. 1\uc6d4 7\uc77c\uc5d0 \uc5c5\ub370\uc774\ud2b8\uac00 \ub098\uc62c \uac83\uc774\ub77c\uace0 \uc608\uace0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://nextjs.org/blog/next-16-1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/next-16-1</a><p data-notion-block-id=\\"2d0e548d-8a8e-80f0-9305-ea54060f7cd3\\">Next.js 16.1\ubc84\uc804\uc774 \ub418\uba74\uc11c \uc5ec\ub7ec \uc0c8\ub85c\uc6b4 \uae30\ub2a5, \ud2b9\ud788 \ub514\ubc84\uae45\uacfc dev \ud658\uacbd \uac1c\uc120\uc744 \uc774\ub8e8\uc5b4\ub0c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://developer.chrome.com/blog/chrome-devtools-mcp-debug-your-browser-session?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/chrome-devtools-mcp-debug-your-browser-session?hl=ko</a><p data-notion-block-id=\\"2d1e548d-8a8e-80bc-a14f-f20805dd2d83\\">Chrome DevTools MCP\uc5d0\uc11c \uc2e4\uc81c \ube0c\ub77c\uc6b0\uc800 \uc138\uc158\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\ub3c4\ub85d \ubc14\ub00c\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/facebook/hermes/blob/static_h/doc/blog/2025-12-12-new-way-to-contribute.md\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/facebook/hermes/blob/static_h/doc/blog/2025-12-12-new-way-to-contribute.md</a><p data-notion-block-id=\\"2d1e548d-8a8e-8022-af7a-d5d3cb23c476\\">Hermes\uc5d0 \uae30\uc5ec\ud558\uae30 \uc27d\uac8c \ucee4\ubba4\ub2c8\ud2f0 \uae30\ubc18 JSI \ud655\uc7a5\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc11c \ub9ce\uc740 \uae30\uc5ec\ub97c \ubc1b\uace0 \uc788\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p>"}')}}]);